def get_deprecation_message(self, msg, version=None, date=None, removed=False, collection_name=None):
    '''Format a deprecation or removal with its release context.'''
    if collection_name is None:
        value = date if date is not None else version
        if isinstance(value, string_types) and ':' in value:
            tagged_collection, value = value.split(':', 1)
            if '.' in tagged_collection:
                collection_name = tagged_collection
                if date is not None:
                    date = value
                else:
                    version = value

    if collection_name == 'ansible.builtin':
        collection_name = 'Ansible-base'

    if removed:
        if date and collection_name:
            return '[DEPRECATED]: %s was removed from %s on %s.\nPlease update your playbooks.' % (msg, collection_name, date)
        if version and collection_name:
            return '[DEPRECATED]: %s was removed in version %s of %s.\nPlease update your playbooks.' % (msg, version, collection_name)
        if date:
            return '[DEPRECATED]: %s was removed after %s.\nPlease update your playbooks.' % (msg, date)
        if version:
            return '[DEPRECATED]: %s was removed in version %s.\nPlease update your playbooks.' % (msg, version)
        if collection_name:
            return '[DEPRECATED]: %s was removed in a previous release of %s.\nPlease update your playbooks.' % (msg, collection_name)
        return '[DEPRECATED]: %s.\nPlease update your playbooks.' % msg

    if date:
        if collection_name:
            suffix = 'in a release of %s after %s' % (collection_name, date)
        else:
            suffix = 'in a release after %s' % date
    elif version:
        if collection_name:
            suffix = 'in version %s of %s' % (version, collection_name)
        else:
            suffix = 'in version %s' % version
    elif collection_name:
        suffix = 'in a future release of %s' % collection_name
    else:
        suffix = 'in a future release'

    return ('[DEPRECATION WARNING]: %s. This feature will be removed %s. '
            'Deprecation warnings can be disabled by setting deprecation_warnings=False in ansible.cfg.\n\n') % (msg, suffix)

def deprecated(self, msg, version=None, removed=False, date=None, collection_name=None):
    ''' used to print out a deprecation message.'''

    if not removed and not C.DEPRECATION_WARNINGS:
        return

    new_msg = self.get_deprecation_message(msg, version=version, date=date, removed=removed, collection_name=collection_name)
    if removed:
        raise AnsibleError(new_msg)

    wrapped = textwrap.wrap(new_msg, self.columns, drop_whitespace=False)
    new_msg = "\n".join(wrapped) + "\n"

    if new_msg not in self._deprecations:
        self.display(new_msg.strip(), color=C.COLOR_DEPRECATE, stderr=True)
        self._deprecations[new_msg] = 1

def warning(self, msg, formatted=False):

    if not formatted:
        new_msg = "[WARNING]: %s" % msg
        wrapped = textwrap.wrap(new_msg, self.columns)
        new_msg = "\n".join(wrapped) + "\n"
    else:
        new_msg = "\n[WARNING]: \n%s" % msg

    if new_msg not in self._warns:
        self.display(new_msg, color=C.COLOR_WARN, stderr=True)
        self._warns[new_msg] = 1

def system_warning(self, msg):
    if C.SYSTEM_WARNINGS:
        self.warning(msg)

